#!/bin/bash
# Second round of faction concept sheets: factions as civilisations with their own identity, not creatures of a biome.
# Each sheet is a rank ladder (fodder, specialist, elite, heavy) the way a faction reads in play.
CX="/c/Program Files/WindowsApps/OpenAI.Codex_26.1106.6628.0_x64__2p2nqsd0c76g0/app/resources/codex.exe"
cd "$(dirname "$0")"
mkdir -p concepts
cd concepts
COMMON="Match the rendering style of the attached style sheet exactly (stylized 3D game art, saturated colour, clean readable shapes, strong distinct silhouettes, soft studio lighting). Lay it out as a game enemy-faction concept sheet on a plain dark navy background, landscape 16:9: four full-body characters standing side by side in a line-up, ordered from the weakest rank on the left to the heaviest on the right, each clearly separated, all sharing one unmistakable faction look. Original designs only: do not resemble any existing video game's characters. No text, no labels, no logos, no borders, no environment."
gen () { # name prompt
  [ -f "$1.png" ] && { echo "skip $1"; return; }
  "$CX" exec --skip-git-repo-check -s workspace-write "Use your built-in image generation tool to generate one image: $2 $COMMON Save the resulting PNG into the current directory as $1.png. Reply with only the saved file path." -i ../refs/style_sheet.webp < /dev/null > "$1.log" 2>&1
  [ -f "$1.png" ] && echo "ok $1" || echo "FAIL $1"
}
gen driftkin "The Driftkin: a spacefaring clan of nomad salvagers and raiders who strip wrecks. Small, wiry, long-limbed two-armed humanoid aliens in patched pressure suits with sailcloth cloaks and scarves, round brass lantern-lens masks, tool belts and salvaged mismatched gear. Palette: faded teal cloth, rusted brass and copper, warm yellow lamp glow. Rank 1: a small scrappy scavenger with a crude scrap pistol. Rank 2: a cloaked marksman with a very long salvaged rifle and a hood. Rank 3: a lean raider captain with a grapple-hook gauntlet, a bladed staff and a tattered banner on its back. Rank 4: a hulking patchwork salvage walker suit piloted by a small Driftkin visible in its open cockpit, with a cutting-torch arm and a magnet claw." &
gen combine "The Dredge Combine: a ruthless interstellar strip-mining corporation's armed workforce. Broad, heavy, bipedal aliens sealed in thick industrial pressure armour with glowing orange visor slits, hazard stripes, hoses and tanks. Palette: dark gunmetal and olive green armour, hazard yellow-and-black markings, hot orange lights. Rank 1: a stocky labourer-soldier with a rivet gun. Rank 2: a shield bearer carrying a tall slab-like riot barricade and a short gun. Rank 3: a foreman in a taller suit with shoulder floodlights, a command antenna and a heavy autocannon. Rank 4: a huge exo-rig heavy with a rock drill on one arm, a mortar launcher on its back and thick piston legs." &
gen bloom "The Bloom: a parasitic alien growth that takes over other creatures and spreads. Hosts are pale bone-white husks cracked open and overgrown with glowing magenta and violet crystalline coral growths, with trailing luminous filaments and no visible eyes. Palette: bone white, deep black, glowing magenta and violet. Rank 1: a small hunched sprinting husk with one arm replaced by a magenta crystal blade. Rank 2: a floating robed husk caster lifted off the ground by filaments, hands glowing, with a halo of magenta shards. Rank 3: a tall overgrown host of a reptilian alien with a frill, half its body replaced by jagged magenta growths. Rank 4: a towering mass of several fused husks with a huge glowing magenta core in its chest and heavy crystal club arms." &
gen warden2 "The Wardens: ancient guardian machines left by a vanished civilisation, built of carved stone and hard light. Matte black and dark grey carved stone segments that do not touch, held together by pale-green light, with thin gold inlay and a single bright light slit instead of a face. Palette: black stone, pale green light, thin gold lines. Rank 1: a small floating ring-shaped sentry, a broken stone ring orbiting a green light. Rank 2: a slender four-legged stone strider with a beam emitter on a long neck. Rank 3: a tall sentinel with a broad torso, a solid attached head with a vertical light slit, a hard-light tower shield and a short beam glaive. Rank 4: a massive floating monolith of separate black stone blocks orbiting a bright green core." &
wait
echo ALLDONE
